Select-String -LiteralPath (Join-Path $dir 'R68_FINAL_NODE_TEST.txt') -Pattern '^ℹ (?:tests|pass|fail)|^✖'|Select-Object -Last 12|ForEach-Object{Write-Output $_.Line}
