'use strict';
const fs=require('node:fs');
const {liveChatObservation}=require('E:\\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6\\app\\r68-live-chat-observability.js');
(async()=>{
 const state=JSON.parse(fs.readFileSync('E:\\WebAIBridge\\app\\data\\state.json','utf8'));
 const cfg=JSON.parse(fs.readFileSync('E:\\WebAIBridge\\app\\data\\supervisor-watchdog.json','utf8'));
 const scanned=await liveChatObservation({
  profiles:state.aiProfiles||[],supervisor:cfg,managedChats:cfg.managedChats||[],
