  getTargets:async port=>{
   const response=await fetch('http://127.0.0.1:'+port+'/json/list',{signal:AbortSignal.timeout(3000)});
   if(!response.ok) throw new Error('CDP_STATUS_'+response.status);
   return response.json();
  }
 });
 console.log(JSON.stringify({contract:scanned.contract,scanComplete:scanned.scanComplete,configuredPortCount:scanned.configuredPortCount,openCount:scanned.openCount,unregisteredOpenCount:scanned.unregisteredOpenCount,registeredCount:scanned.chats.filter(x=>x.registered).length,assignmentCount:scanned.assignments.length,timelineCount:scanned.timeline.length,sourceOk:scanned.sources.map(p=>({port:p.port,ok:p.ok,pageCount:p.pageCount,error:p.ok?'':p.error})),unknownVisible:scanned.chats.filter(x=>x.visibility==='open_unregistered').length,allNoMutation:scanned.guardrails.noSend && !scanned.guardrails.providerMutation}));
})().catch(e=>{console.error('R68_SMOKE_FAILED '+String(e.message||e));process.exitCode=1});

